return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'uk','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:36+00:00','po-revision-date'=>'2026-10-31T05:53:36+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Доповнює відсутні переклади для плагінів і тем, які вже встановлено на вашому сайті.','Translations'=>'Переклади','Babilim Settings'=>'Налаштування Babilim','Settings'=>'Налаштування','You are not allowed to do this.'=>'Вам не дозволено виконувати цю дію.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Виберіть менше компонентів: щонайбільше %1$d операцій за один запуск (ви вибрали %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Цей компонент не встановлено на цьому сайті, тому запросити для нього переклад неможливо.','Already installed.'=>'Уже встановлено.','Downloaded and installed.'=>'Завантажено та встановлено.','Babilim has not been enabled for this site yet.'=>'Babilim ще не увімкнено для цього сайту.','No build is available to download for this locale.'=>'Для цієї локалі немає збірки для завантаження.','Rolled back to the previous build.'=>'Повернуто до попередньої збірки.','Rolled back and reported.'=>'Відкочено та повідомлено.','Rolled back, but the report could not be sent: %s'=>'Відкочено, але надіслати звіт не вдалося: %s','Removed.'=>'Видалено.','Translation requested.'=>'Переклад запрошено.','This component was already uploaded. Babilim is checking it now.'=>'Цей компонент уже завантажено. Babilim зараз його перевіряє.','Upload cancelled.'=>'Завантаження скасовано.','Upload complete — translation requested.'=>'Завантаження завершено — переклад запрошено.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Цей компонент не вказує номер версії, тому запросити для нього переклад неможливо.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Номер версії цього компонента довший за %d символів, чого Babilim не може обробити, тому запросити для нього переклад неможливо.','A translation cannot be requested for that locale on this site right now.'=>'Зараз на цьому сайті неможливо запросити переклад для цієї локалі.','Thank you. Your report was sent.'=>'Дякуємо. Ваш звіт надіслано.','This report does not name a valid plugin or theme and locale.'=>'У цьому звіті не вказано дійсний плагін чи тему та локаль.','Please choose a category for this report.'=>'Виберіть категорію для цього звіту.','This report is missing a valid build to report against.'=>'У цьому звіті немає дійсної збірки, щодо якої подається звіт.','This build is not one this site currently knows about for this component/locale.'=>'Цей сайт наразі не знає такої збірки для цього компонента/локалі.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Поле «%1$s» задовге: воно містить %2$d символів, а ліміт — %3$d. Нічого не надіслано; скоротіть його та спробуйте ще раз.','Original string'=>'Оригінальний рядок','String context'=>'Контекст рядка','Current translation'=>'Поточний переклад','Suggested translation'=>'Запропонований переклад','Note (optional)'=>'Примітка (необов’язково)','Where you saw this (optional)'=>'Де ви це побачили (необов’язково)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Синхронізацію Babilim тимчасово затримано службою (обмеження частоти запитів); наступна спроба — після %s.','That is not a valid WordPress locale code. Nothing was saved.'=>'Це недійсний код локалі WordPress. Нічого не збережено.','Settings saved.'=>'Налаштування збережено.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Якщо це увімкнено, під час видалення плагіна також буде стерто ідентифікатор цього сайту. Платну ліцензію, прив’язану до цього сайту, згодом не можна буде відновити автоматично; щоб повернути її, вам доведеться звернутися до підтримки Babilim за адресою %s.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim налаштовано стерти ідентифікатор цього сайту під час видалення плагіна. Платну ліцензію, прив’язану до цього сайту, тоді не можна буде відновити автоматично; вам доведеться звернутися до підтримки Babilim за адресою %s. Щоб зберегти ідентифікатор, натисніть «Скасувати», зніміть позначку «Видалити всі дані Babilim під час видалення плагіна» в налаштуваннях Babilim і деактивуйте знову. Усе одно деактивувати?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d сайт у цій мережі налаштовано стерти свій ідентифікатор Babilim під час видалення плагіна. Платну ліцензію, прив’язану до цього сайту, тоді не можна буде відновити автоматично; вам доведеться звернутися до підтримки Babilim за адресою %2$s. Щоб зберегти ідентифікатор, натисніть «Скасувати», зніміть позначку «Видалити всі дані Babilim під час видалення плагіна» в налаштуваннях Babilim цього сайту і деактивуйте знову. Усе одно деактивувати?' . "\0" . '%1$d сайти в цій мережі налаштовано стерти свій ідентифікатор Babilim під час видалення плагіна. Платні ліцензії, прив’язані до цих сайтів, тоді не можна буде відновити автоматично; вам доведеться звернутися до підтримки Babilim за адресою %2$s. Щоб зберегти ідентифікатори, натисніть «Скасувати», зніміть позначку «Видалити всі дані Babilim під час видалення плагіна» в налаштуваннях Babilim кожного сайту і деактивуйте знову. Усе одно деактивувати?' . "\0" . '%1$d сайтів у цій мережі налаштовано стерти свій ідентифікатор Babilim під час видалення плагіна. Платні ліцензії, прив’язані до цих сайтів, тоді не можна буде відновити автоматично; вам доведеться звернутися до підтримки Babilim за адресою %2$s. Щоб зберегти ідентифікатори, натисніть «Скасувати», зніміть позначку «Видалити всі дані Babilim під час видалення плагіна» в налаштуваннях Babilim кожного сайту і деактивуйте знову. Усе одно деактивувати?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'У цій мережі забагато сайтів, щоб перевіряти їх по одному, а деякі з них можуть бути налаштовані стерти свій ідентифікатор Babilim під час видалення плагіна. Платну ліцензію, прив’язану до такого сайту, тоді не можна буде відновити автоматично; вам доведеться звернутися до підтримки Babilim за адресою %s. Щоб зберегти ідентифікатори, натисніть «Скасувати», зніміть позначку «Видалити всі дані Babilim під час видалення плагіна» в налаштуваннях Babilim кожного сайту і деактивуйте знову. Усе одно деактивувати?','Open Babilim settings'=>'Відкрити налаштування Babilim','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim не вдалося перевірити цей сайт, тому нічого не завантажується й не встановлюється.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Сервіс не зміг зв’язатися з вашим сайтом. Імовірно, запит блокує брандмауер, плагін безпеки або правило хостингу; дозвольте запити до /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Ваш сайт відповідав надто довго. Спробуйте пізніше та переконайтеся, що ваш хостинг не надто повільний і не перевантажений.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Ваш сайт відповів, але не так, як очікувалося. REST API може бути переписаний іншим плагіном, або цю кінцеву точку може бути кешовано; виключіть /wp-json/babilim/v1/challenge з кешування та переписування.','Please check that your site can be reached from the internet, then try again.'=>'Переконайтеся, що ваш сайт доступний з інтернету, і спробуйте ще раз.','Re-verify'=>'Перевірити повторно','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Цей сайт перевищує розмір, який сервіс приймає за одну синхронізацію, тому деякі елементи пропущено: компонентів — %1$d, локалей — %2$d.','This site is verified.'=>'Цей сайт перевірено.','Registration restarted.'=>'Реєстрацію перезапущено.','Sync complete.'=>'Синхронізацію завершено.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim вмикається та перевіряє цей сайт… Перезавантажте сторінку або дочекайтеся завершення запланованої перевірки.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim не вдалося завершити вмикання (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Хостинг, що обробляє лише один PHP-запит одночасно, не може виконати цей крок.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim увімкнено: цей сайт перевірено, знайдено %d компонент.' . "\0" . 'Babilim увімкнено: цей сайт перевірено, знайдено %d компоненти.' . "\0" . 'Babilim увімкнено: цей сайт перевірено, знайдено %d компонентів.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim вимкнено. Більше нічого не надсилається; уже встановлені переклади продовжують працювати.','Supplementary translation index rebuilt.'=>'Додатковий індекс перекладів перебудовано.','Sweep complete: %d file deleted.'=>'Очищення завершено: видалено %d файл.' . "\0" . 'Очищення завершено: видалено %d файли.' . "\0" . 'Очищення завершено: видалено %d файлів.','Removed %d installed component.'=>'Вилучено %d встановлений компонент.' . "\0" . 'Вилучено %d встановлені компоненти.' . "\0" . 'Вилучено %d встановлених компонентів.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Автоматичне встановлення тепер вимкнено; за потреби знову увімкніть його в налаштуваннях.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim знаходить плагіни та теми на цьому сайті, які не мають перекладу вашою мовою, і встановлює переклад для кожного з них.','Languages found on this site: %s.'=>'Мови, знайдені на цьому сайті: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Доступні переклади можна встановити одним клацанням, а відсутні — запросити. Після цього нові переклади й оновлення встановлюються автоматично (на безкоштовному плані — лише для плагінів і тем, які вже займають безкоштовний слот).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Безкоштовний план охоплює обмежену кількість плагінів і тем; вашу точну квоту буде показано в розділі «Налаштування» після ввімкнення Babilim.','What is sent when you enable Babilim'=>'Що надсилається, коли ви вмикаєте Babilim','Enabling…'=>'Вмикання…','Enable Babilim'=>'Увімкнути Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Натискаючи «Увімкнути», ви погоджуєтеся надіслати до Babilim інформацію, перелічену вище.','Check again now'=>'Перевірити ще раз зараз','Babilim installed %d translation automatically since your last visit.'=>'Babilim автоматично встановив %d переклад після вашого останнього візиту.' . "\0" . 'Babilim автоматично встановив %d переклади після вашого останнього візиту.' . "\0" . 'Babilim автоматично встановив %d перекладів після вашого останнього візиту.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim вмикається та перевіряє цей сайт… (остання спроба: %s)','Check again'=>'Перевірити ще раз','No components synced yet.'=>'Жодного компонента ще не синхронізовано.','%d succeeded'=>'Успішно: %d' . "\0" . 'Успішно: %d' . "\0" . 'Успішно: %d','%d skipped'=>'Пропущено: %d' . "\0" . 'Пропущено: %d' . "\0" . 'Пропущено: %d','%d failed'=>'Помилок: %d' . "\0" . 'Помилок: %d' . "\0" . 'Помилок: %d','%d not yet tried'=>'Ще не спробувано: %d' . "\0" . 'Ще не спробувано: %d' . "\0" . 'Ще не спробувано: %d','%1$s nothing to do.'=>'%1$s немає дій для виконання.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Масове завантаження:','Bulk update:'=>'Масове оновлення:','Bulk request:'=>'Масовий запит:','per day'=>'на день','Wrong meaning'=>'Неправильне значення','Wrong term'=>'Неправильний термін','Broken placeholder'=>'Пошкоджений заповнювач','Wrong for this context'=>'Неправильно для цього контексту','Wrong plural form'=>'Неправильна форма множини','Negation reversed'=>'Заперечення обернено','Translation does not load'=>'Переклад не завантажується','problem report categoryOther'=>'Інше','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Продовження…','Continue next batch (%d left)'=>'Продовжити наступну партію (залишилося: %d)','Search components'=>'Пошук компонентів','These are the languages this site uses. You can change them in %s.'=>'Це мови, які використовує цей сайт. Ви можете змінити їх у %s.','Upload this component?'=>'Завантажити цей компонент?','There is no upload waiting for confirmation.'=>'Немає завантаження, що очікує підтвердження.','Back'=>'Назад','To translate this component, Babilim needs its source.'=>'Щоб перекласти цей компонент, Babilim потрібен його вихідний код.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Весь каталог плагіна або теми %1$s (версія %2$s) буде завантажено до Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Якщо цей каталог містить ключі, журнали або дані клієнтів, їх також буде завантажено. Сервіс видаляє поширені конфіденційні файли (конфігурацію, середовище, дампи бази даних, журнали, ключі), але не може гарантувати, що знайде все.','The upload is kept until you ask Babilim to delete it.'=>'Завантажене зберігається, доки ви не попросите Babilim його видалити.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Воно зберігається хостинг-провайдером сервісу та обробляється моделями ШІ для створення перекладу.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Оригінальний текст і створені з нього переклади будуть надані іншим сайтам, які встановлюють ту саму версію.','By continuing you confirm that you have the right to upload this component.'=>'Продовжуючи, ви підтверджуєте, що маєте право завантажувати цей компонент.','Upload and request'=>'Завантажити й надіслати запит','Uploading…'=>'Завантаження…','Cancel'=>'Скасувати','Uploading'=>'Завантаження','There is no upload in progress.'=>'Немає завантаження, що виконується.','Uploading part %1$d of %2$d…'=>'Завантаження частини %1$d з %2$d…','Continue'=>'Продовжити','Confirm'=>'Підтвердити','Remove'=>'Вилучити','Roll back'=>'Відкотити','Nothing to confirm.'=>'Нічого підтверджувати.','Choose a language'=>'Виберіть мову','Roll back and report'=>'Відкотити й повідомити','Report a problem'=>'Повідомити про проблему','Nothing to choose.'=>'Нічого вибирати.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Виберіть мову.','Supplementary translations'=>'Додаткові переклади','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Внесок кожного компонента в спільне доповнення домену default для кожної локалі.','Component'=>'Компонент','Language'=>'Мова','Included in index'=>'Включено до індексу','Entries'=>'Записи','Conflicting keys'=>'Конфліктні ключі','Yes'=>'Так','No — component inactive'=>'Ні — компонент неактивний','No — installed version differs from the active one'=>'Ні — встановлена версія відрізняється від активної','No — component removed'=>'Ні — компонент видалено','No'=>'Ні','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Це може зробити лише адміністратор мережі, оскільки це змінює файли перекладу, спільні для всіх сайтів цієї мережі.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim не вдалося завершити перевірку цього сайту (сервіс не зміг зв’язатися з ним у відповідь). Реєстрацію призупинено.','This site already has an active registration that can no longer be recovered automatically.'=>'Цей сайт уже має активну реєстрацію, яку більше не можна відновити автоматично.','Restart registration'=>'Почати реєстрацію заново','Babilim settings'=>'Налаштування Babilim','General'=>'Загальні','Advanced'=>'Додатково','Languages'=>'Мови','Automatic installs'=>'Автоматичне встановлення','Install available translations automatically'=>'Автоматично встановлювати доступні переклади','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'У безкоштовному плані автоматично встановлюються лише компоненти, які вже займають один із ваших вільних слотів, тож новий слот не використовується.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Цей сайт належить до мережі multisite, яка не встановлює нові переклади автоматично. Уже встановлені переклади все одно оновлюються.','Custom overrides'=>'Власні перевизначення','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Зберігати мої власні перевизначення перекладів під час повного очищення або видалення цього плагіна.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Файли перекладу, які ви розмістили в %s, завжди мають пріоритет над файлами Babilim. Вони зберігаються, доки ви не знімете цей прапорець.','Uninstall'=>'Видалення','Delete all Babilim data on uninstall'=>'Видалити всі дані Babilim під час видалення плагіна','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'За замовчуванням вимкнено: видалення плагіна зберігає ідентичність цього сайту, тож після перевстановлення її можна використати повторно.','Account'=>'Обліковий запис','Save changes'=>'Зберегти зміни','Disable Babilim'=>'Вимкнути Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'Установлені переклади збережуться, але подальші перевірки й завантаження не виконуватимуться.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Вимкнути Babilim? Установлені переклади збережуться, але подальші перевірки й завантаження не виконуватимуться.','This site is not registered with Babilim yet.'=>'Цей сайт ще не зареєстровано в Babilim.','This site is already licensed. Reload the page.'=>'Цей сайт уже має ліцензію. Перезавантажте сторінку.','Checkout is not available for this site right now.'=>'Оформлення замовлення для цього сайту зараз недоступне.','Could not start checkout: %s'=>'Не вдалося розпочати оформлення замовлення: %s','Babilim is not enabled.'=>'Babilim не ввімкнено.','Not registered yet'=>'Ще не зареєстровано','Not verified'=>'Не перевірено','Verified'=>'Перевірено','Status'=>'Статус','Licensed'=>'Ліцензовано','Partner'=>'Партнер','Free'=>'Безкоштовно','License'=>'Ліцензія','Upgrade this site'=>'Перейти на платну версію для цього сайту','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Одноразова покупка для цього сайту: %1$s %2$s. Включає всі майбутні оновлення перекладів. Оплату обробляє Paddle у новій вкладці.','This issues a new restore code and the previous one stops working. Continue?'=>'Буде видано новий код відновлення, а попередній перестане працювати. Продовжити?','Show a new restore code'=>'Показати новий код відновлення','rc_…'=>'rc_…','Restore code'=>'Код відновлення','Restore purchase'=>'Відновити покупку','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Раніше купували ліцензію для цього домену? Введіть код відновлення, який ви отримали під час оформлення замовлення.','That does not look like a restore code.'=>'Це не схоже на код відновлення.','This restore code was not recognised for this site.'=>'Цей код відновлення не розпізнано для цього сайту.','Too many attempts. Try again tomorrow.'=>'Забагато спроб. Спробуйте завтра.','This site must be verified first.'=>'Спочатку потрібно підтвердити цей сайт.','Could not restore the purchase: %s'=>'Не вдалося відновити покупку: %s','Purchase restored. This site is now licensed.'=>'Покупку відновлено. Цей сайт тепер має ліцензію.','This site has no purchase to show a code for.'=>'Для цього сайту немає покупки, для якої можна показати код.','Could not show a new restore code: %s'=>'Не вдалося показати новий код відновлення: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Ваш новий код відновлення: %s. Збережіть його в надійному місці — попередній код більше не працює.','What is sent when Babilim checks this site'=>'Що надсилається, коли Babilim перевіряє цей сайт','(detected)'=>'(виявлено)','No language is managed yet.'=>'Ще немає мов під керуванням Babilim.','Babilim adds translations for every language checked here.'=>'Babilim додає переклади для кожної мови, позначеної тут.','Add another language'=>'Додати ще одну мову','Choose a language…'=>'Виберіть мову…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Не вдалося завантажити з сервісу повний список локалей WordPress.org, тому наразі не можна додати іншу мову.','Theme'=>'Тема','Plugin'=>'Плагін','Free quota'=>'Безкоштовна квота','Downloads: %1$d/%2$d (%3$s)'=>'Завантаження: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Індекс додаткових перекладів','Built'=>'Зібрано','Included'=>'Включено','Excluded'=>'Виключено','Already in WordPress core'=>'Уже є в ядрі WordPress','Supplementary translation maintenance'=>'Обслуговування додаткового індексу перекладів','Maintenance status is not available right now.'=>'Статус обслуговування наразі недоступний.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Очищення було призупинено %1$s: %2$s. Нічого не було видалено.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Останнє очищення %1$s: нових позначених файлів: %2$d, файлів видалено: %3$d, записів вилучено: %4$d.','No cleanup has run yet.'=>'Очищення ще не виконувалося.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Запис в індекс перекладів конфліктував з іншим запитом %1$s (%2$s) і не був застосований; збережено найновішу версію.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Запис в індекс перекладів %1$s (%2$s) не вдалося завершити, і його не застосовано (%3$s).','Maintenance'=>'Обслуговування','Rebuild index now'=>'Перебудувати індекс зараз','Sweep now'=>'Очистити зараз','Danger zone'=>'Небезпечна зона','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Видаляє всі мовні файли, встановлені Babilim для кожного плагіна та кожної теми на цьому сайті.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Видалити все, що встановив Babilim? Це видалить усі мовні файли, які він встановив для кожного плагіна та кожної теми на цьому сайті.','Remove everything Babilim installed'=>'Видалити все, що встановив Babilim','This string is too long to be sent as a report, so no report form is offered for it.'=>'Цей рядок задовгий для надсилання у звіті, тому форма звіту для нього не пропонується.','Category'=>'Категорія','Choose a category…'=>'Оберіть категорію…','Roll back and send report'=>'Відкотити й надіслати звіт','Send report'=>'Надіслати звіт','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Частина тексту цього компонента жорстко закодована його автором і не може бути перекладена мовним пакетом.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Входить до складу теми','Bundled with the plugin'=>'Входить до складу плагіна','Upload was not accepted'=>'Завантаження не прийнято','Upload expired before it finished'=>'Термін дії завантаження минув до його завершення','No translation'=>'Немає перекладу','Upload in progress — continue or cancel'=>'Триває завантаження — продовжити або скасувати','Scheduled, waiting to be processed'=>'Заплановано, очікує на обробку','Translating…'=>'Переклад…','Translation failed'=>'Не вдалося перекласти','Free quota used'=>'Безкоштовну квоту використано','Needs a paid license'=>'Потрібна платна ліцензія','Not supported'=>'Не підтримується','Status unknown'=>'Статус невідомий','translation statusInstalled'=>'Встановлено','Update available'=>'Доступне оновлення','Removed after a failed integrity check'=>'Видалено після невдалої перевірки цілісності','Installed · built for %s, new version scheduled'=>'Встановлено · створено для %s, нову версію заплановано','Installed · built for a different version, new version scheduled'=>'Встановлено · створено для іншої версії, нову версію заплановано','Installed · built for %s, translating the new version…'=>'Встановлено · створено для %s, перекладається нова версія…','Installed · built for a different version, translating the new version…'=>'Встановлено · створено для іншої версії, перекладається нова версія…','Installed · built for %1$s, this site has %2$s'=>'Встановлено · створено для %1$s, на цьому сайті %2$s','Installed · built for %s'=>'Встановлено · створено для %s','Installed · built for a different version'=>'Встановлено · створено для іншої версії','Installed · built for %s, new version failed'=>'Встановлено · створено для %s, не вдалося створити переклад нової версії','Installed · built for a different version, new version failed'=>'Встановлено · створено для іншої версії, не вдалося створити переклад нової версії','Installed · built for %s, new version needs a paid license'=>'Встановлено · створено для %s, нова версія потребує платної ліцензії','Installed · built for a different version, new version needs a paid license'=>'Встановлено · створено для іншої версії, нова версія потребує платної ліцензії','Installed · built for %s, free quota used'=>'Встановлено · зібрано для %s, безкоштовну квоту використано','Installed · built for a different version, free quota used'=>'Встановлено · зібрано для іншої версії, безкоштовну квоту використано','translation statusAvailable'=>'Доступно','Installed · %s'=>'Встановлено · %s','Available · %s'=>'Доступно · %s','Update'=>'Оновити','Download'=>'Завантажити','Updating…'=>'Оновлення…','Downloading…'=>'Завантаження…','Retry request'=>'Повторити запит','Request newer translation'=>'Запросити новіший переклад','Request translation'=>'Запросити переклад','Requesting…'=>'Надсилання запиту…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Запит на переклад використовує один із ваших вільних слотів, якщо цей компонент ще не використовує його. Невдалий переклад не повертає слот.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Якщо цей компонент ще не використовує один із ваших вільних слотів, запит на переклад займе один. Невдалий переклад не повертає слот. Продовжити?','No plugins or themes found.'=>'Плагінів або тем не знайдено.','Clear filters'=>'Очистити фільтри','No components match these filters. %s'=>'Жоден компонент не відповідає цим фільтрам. %s','Select all'=>'Вибрати все','All'=>'Усі','Available'=>'Доступно','Updates'=>'Оновлення','Requestable'=>'Можна запросити','Installed'=>'Встановлено','Plugins'=>'Плагіни','Themes'=>'Теми','All languages'=>'Усі мови','%d to install'=>'%d для встановлення' . "\0" . '%d для встановлення' . "\0" . '%d для встановлення','Language:'=>'Мова:','Bulk actions apply to every matching language of each selected component.'=>'Групові дії застосовуються до кожної відповідної мови кожного вибраного компонента.','Bulk actions apply only to the selected language of each selected component.'=>'Групові дії застосовуються лише до вибраної мови кожного вибраного компонента.','Version %s'=>'Версія %s','Theme · %s'=>'Тема · %s','Plugin · %s'=>'Плагін · %s','Remove the %2$s translation of %1$s from this site?'=>'Видалити переклад %2$s для %1$s з цього сайту?','Roll back the %2$s translation of %1$s to the previous build?'=>'Відкотити переклад %2$s для %1$s до попередньої збірки?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Реєстраційний виклик має неочікуваний формат.','That is not a valid build identifier.'=>'Це недійсний ідентифікатор збірки.','Refusing to write outside the Babilim language-file directory.'=>'Відмовлено в записі за межами каталогу мовних файлів Babilim.','Could not write the downloaded package to disk.'=>'Не вдалося записати завантажений пакет на диск.','Unexpected HTTP %d response.'=>'Неочікувана відповідь HTTP %d.','This site\'s URL, so the service can verify you own it.'=>'URL-адреса цього сайту, щоб сервіс міг переконатися, що вона належить вам.','Your WordPress version, to serve compatible translation files.'=>'Ваша версія WordPress, щоб надавати сумісні файли перекладу.','Your PHP version, for compatibility.'=>'Ваша версія PHP, для перевірки сумісності.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Версія самого цього плагіна, щоб сервіс міг повідомити вам про потребу оновлення, якщо вона надто стара для взаємодії.','This site\'s configured locale.'=>'Налаштована локаль цього сайту.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Кожна локаль, що використовується на цьому сайті (локаль сайту, встановлені мовні пакети, локалі користувачів і додані вами вручну). Жодна локаль не розглядається інакше, ніж інша.','(a public key generated for this site)'=>'(публічний ключ, згенерований для цього сайту)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Публічний ключ встановлення цього сайту, який використовується для підтвердження того, що запити справді надходять із цього сайту. Надсилається лише публічна частина.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Для кожного встановленого плагіна або теми: slug, версія, один або кілька text domain, наявність у каталозі wp.org, власні вбудовані локалі та локалі, для яких ви вже встановили переклад Babilim.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Лише коли ви підтверджуєте завантаження для плагіна або теми, яких немає на WordPress.org: увесь каталог цього компонента у вигляді zip-архіву.','(generic codes and coordinates only)'=>'(лише загальні коди та координати)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'До 20 діагностичних подій в очікуванні (наприклад, файл, що не пройшов перевірку цілісності), кожна містить лише код, компонент і локаль, але ніколи вмісту рядків чи перекладеного тексту.','Unsafe locale: %s'=>'Небезпечна локаль: %s','Manifest unavailable: %s'=>'Маніфест недоступний: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Не вдалося визначити активні компоненти; наявний об’єднаний індекс залишено без змін.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Не вдалося визначити встановлені плагіни/теми; очищення пропущено, нічого не видалено.','Sweep aborted without orphaning anything: %s.'=>'Очищення перервано без створення осиротілих записів: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Очищення виконано, але деякі його зміни не вдалося записати в індекс перекладів; наступне очищення повторить спробу.','component kind in the sweep brake messagetheme'=>'тема','component kind in the sweep brake messageplugin'=>'плагін','it would orphan every managed %1$s component (%2$d of %2$d)'=>'це зробить осиротілими всі керовані компоненти типу «%1$s» (%2$d з %2$d)','it would orphan %1$d of %2$d managed components (more than half)'=>'це зробить осиротілими %1$d з %2$d керованих компонентів (більше половини)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Об’єднаний індекс для «%s» перебудовано, але індекс перекладів не зміг його записати; наступна перебудова повторить спробу.','Could not write the staged merged index.'=>'Не вдалося записати проміжний об’єднаний індекс.','Re-parsed entry count did not match the built index.'=>'Повторно визначена кількість записів не збігається зі створеним індексом.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Не вдалося перемістити об’єднаний індекс для «%s» на місце; попередній індекс (якщо був) видалено, щоб не залишати його частково оновленим. Доповнення для домену default не надаватиметься для цієї локалі до наступної успішної перебудови.','Could not open zip: %s'=>'Не вдалося відкрити zip: %s','Zip has no manifest.json.'=>'У Zip немає manifest.json.','manifest.json in the zip is not valid JSON.'=>'manifest.json в zip-архіві не є коректним JSON.','manifest.json\'s \'%s\' does not match the expected value.'=>'Поле «%s» у manifest.json не відповідає очікуваному значенню.','Another installation is running; try again in a moment.'=>'Виконується інше встановлення; спробуйте ще раз за мить.','Not a valid server_build_id: %s'=>'Недійсний server_build_id: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Тип «%1$s» у маніфесті пакета не збігається із запитаним типом «%2$s».','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'text domain пакета «%1$s» не збігається з копією компонента на цьому сайті («%2$s»), тому пакет не було встановлено.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Указаний домен «%1$s» не збігається ні з власним slug маніфесту пакета «%2$s», ні з його text_domain «%3$s».','Unsafe slug: %s'=>'Небезпечний slug: %s','Unsafe text_domain: %s'=>'Небезпечний text_domain: %s','The package has no %s for its own text domain.'=>'У пакеті немає %s для його власного text domain.','manifest.json is missing or has an invalid \'%s\'.'=>'У manifest.json відсутнє або недійсне поле «%s».','manifest.json is missing or has an invalid \'entries\'.'=>'У manifest.json відсутнє або недійсне поле «entries».','manifest.json is missing or has an invalid \'files\'.'=>'У manifest.json відсутнє або недійсне поле «files».','manifest.json is missing or has an invalid \'extra_domains\'.'=>'У manifest.json відсутнє або недійсне поле «extra_domains».','manifest.json is missing or has an invalid \'build_no\'.'=>'У manifest.json відсутнє або недійсне поле «build_no».','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'Поле «server_build_id» у manifest.json не є дійсним ідентифікатором збірки.','manifest.json\'s \'contract\' is not a valid version string.'=>'Поле «contract» у manifest.json не є дійсним рядком версії.','manifest.json\'s \'status\' must be \'published\'.'=>'Статус у manifest.json має бути «published».','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'Поле «kind» у manifest.json має бути «plugin» або «theme».','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json містить недійсне поле «default_domain_entries».','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json містить недійсне поле «default_domain_files».','expected_manifest is missing or has an invalid \'%s\'.'=>'В expected_manifest відсутнє або недійсне поле «%s».','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'Поле «server_build_id» в expected_manifest не є дійсним ідентифікатором збірки.','No record for %s'=>'Немає запису для %s','One or more served files no longer match the manifest.'=>'Один або кілька наданих файлів більше не відповідають маніфесту.','No previous build to roll back to.'=>'Немає попередньої збірки для відкату.','The change could not be recorded in the translation index; please try again.'=>'Не вдалося записати зміну в індекс перекладів; спробуйте ще раз.','Unknown kind: %s'=>'Невідомий тип: %s','Unsafe domain: %s'=>'Небезпечний домен: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'text domain «%1$s» (%2$s) уже використовується для іншого встановленого компонента (%3$s); нічого не встановлено.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Відкочування перезапише «%1$s» (%2$s), який тепер використовується для іншого встановленого компонента (%3$s); нічого не змінено.','Zip is missing expected file: %s'=>'У zip-архіві відсутній очікуваний файл: %s','sha256 mismatch for %s'=>'Невідповідність sha256 для %s','The package declares no main translation file.'=>'Пакет не оголошує основного файлу перекладу.','Zip is missing expected default file: %s'=>'У zip-архіві відсутній очікуваний файл домену default: %s','sha256 mismatch for default/%s'=>'Невідповідність sha256 для default/%s','Could not stage %s'=>'Не вдалося підготувати %s','Could not stage default/%s'=>'Не вдалося підготувати default/%s','Entry count mismatch for %s'=>'Невідповідність кількості записів для %s','Could not verify entry count for %s'=>'Не вдалося перевірити кількість записів для %s','l10n.php entry count mismatch for %s'=>'Невідповідність кількості записів l10n.php для %s','Default supplement entry count mismatch.'=>'Невідповідність кількості записів доповнення default.','The package produced no servable main translation file.'=>'Пакет не створив придатного до використання основного файлу перекладу.','Could not prepare %s for rollback.'=>'Не вдалося підготувати %s до відкату.','Could not back up %s before replacing it.'=>'Не вдалося створити резервну копію %s перед заміною.','Could not move %s into place.'=>'Не вдалося перемістити %s на місце.','Could not read %s back after moving it into place.'=>'Не вдалося повторно прочитати %s після переміщення на місце.','English (United States)'=>'English (United States)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest недоступний: %s','could not read _manifest.json: %s'=>'не вдалося прочитати _manifest.json: %s','failed to parse _manifest.json: %s'=>'Не вдалося розібрати _manifest.json: %s','_manifest.json has an unexpected structure'=>'_manifest.json має неочікувану структуру','Could not create the package archive.'=>'Не вдалося створити архів пакета.','No writable temporary directory is available for packaging.'=>'Для пакування немає доступного для запису тимчасового каталогу.','A file in the component could not be read, so it was not packaged.'=>'Не вдалося прочитати один із файлів компонента, тому його не було додано до пакета.','Only plugins and themes can be packaged.'=>'Пакувати можна лише плагіни та теми.','The component\'s main file was not found.'=>'Головний файл компонента не знайдено.','The component is not inside the plugins or themes directory.'=>'Компонент не розташований у каталозі плагінів або тем.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim не встиг завершити цей крок і продовжить під час наступної перевірки.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim не зміг верифікувати цей сайт, тому нічого не буде завантажено чи встановлено, доки верифікація не завершиться успішно.','Registration response was missing required fields.'=>'У відповіді на реєстрацію бракувало обов’язкових полів.','No pending challenge to verify.'=>'Немає очікуваного запиту для верифікації.','Verify response was missing site_token.'=>'У відповіді на верифікацію бракувало site_token.','No site id is on file to rotate a token for.'=>'Немає збереженого ідентифікатора Сайту, для якого можна ротувати токен.','Rotate-token response was missing site_token.'=>'У відповіді на ротацію токена бракувало site_token.','nonce must be a hexadecimal string.'=>'nonce має бути шістнадцятковим рядком.','No pending challenge for this nonce.'=>'Для цього nonce немає очікуваного запиту перевірки.','Too many requests.'=>'Забагато запитів.','The service asked this site to wait before syncing again.'=>'Сервіс попросив цей сайт зачекати перед наступною синхронізацією.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Цей сайт має %1$d компонентів для %2$d мов, що потребує %3$d пакетів перевірки; Babilim може обробити щонайбільше %4$d за один запуск. Зменште кількість керованих мов у розділі «Налаштування» або деактивуйте невикористовувані плагіни й теми, а потім натисніть «Перевірити ще раз».','Babilim could not finish checking this site.'=>'Babilim не зміг завершити перевірку цього сайту.','This site\'s address is too long for Babilim to register.'=>'Адреса цього сайту задовга для реєстрації в Babilim.','This site\'s locale code is not one Babilim can register.'=>'Код локалі цього сайту не може бути зареєстрований у Babilim.','The download response was missing a usable location.'=>'У відповіді на завантаження бракувало придатного розташування.','The service\'s upload offer was incomplete.'=>'Пропозиція сервісу щодо вивантаження була неповною.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Цей компонент більший за допустимий сервісом розмір, тому його не можна вивантажити.','The packaged component could not be read.'=>'Не вдалося прочитати запакований компонент.','A part of the upload kept failing, so the upload was cancelled.'=>'Одна з частин вивантаження постійно завершувалася помилкою, тому вивантаження скасовано.','Could not read: %s'=>'Не вдалося прочитати: %s']];